import csv
import io
import re


def parse_csv(raw_csv: str):
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=",", quotechar='"')

    records = []
    try:
        for row in reader:
            if row and any(value.strip() for value in row):
                records.append(row)
    except csv.Error:
        pass

    def looks_like_header(row):
        if len(row) < 2 or re.fullmatch(r"\s*[+-]?(?:\d+(?:\.\d*)?|\.\d+)\s*", row[0]):
            return False
        labels = sum(
            bool(re.fullmatch(r"\s*[\w.-]+\s*", value, flags=re.UNICODE))
            for value in row
        )
        return labels >= max(2, (len(row) + 1) // 2)

    header_index = None
    for index, row in enumerate(records):
        if looks_like_header(row):
            header_index = index
            break

    if header_index is None:
        for index, row in enumerate(records):
            if len(row) >= 2 and not row[0].lstrip().startswith("#"):
                header_index = index
                break

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = [value.strip() for value in records[header_index]]
    width = len(columns)
    rows = []

    for row in records[header_index + 1:]:
        if row and row[0].lstrip().startswith("#") and len(row) == 1:
            continue
        if len(row) > width:
            row = row[:width - 1] + [",".join(row[width - 1:])]
        elif len(row) < width:
            row = row + [""] * (width - len(row))
        rows.append(row)

    return {"columns": columns, "rows": rows}
